profiles=[]
for key,name,group,ids,age,tags,summary,pattern in specs:
    ids=ids.split(); records=[byid[i] for i in ids]; categories=[]
    for i in ids:
        l=old.get(i,byid[i]); e=byid[i]
        categories.append(dict(name=l['title'],age=l['age'],team=l['format'],hardware=l['gear'],age_rule=e.get('age_reference_date') or 'Дату отсечения / класс сверить с действующим местным регламентом.',event_id=i,entry=l['entry'],language=l['language'],note=l['note'],source=l['source'],checked=e['checked']))
    related=list(dict.fromkeys(ids+[e['id'] for e in d['events'] if e['block']=='Соревнования' and re.search(pattern,e['title'],re.I)]))
    if key=='vex': related=[i for i in related if not re.search('RECF|Engage|Achieve|Robofest',byid[i]['title'],re.I)]
    profiles.append(dict(id=key,name=name,group=group,age_summary=age,age_tags=tags.split(),summary=summary,categories=categories,event_ids=related,legacy_ids=[i for i in ids if i in old],
        route=records[0]['entry'],hardware=records[0]['gear'],language=records[0]['language'],
        importance='Редакционная группа по типу маршрута, а не официальный рейтинг всех лиг.',
        strengths=summary,requirements=['Выбрать конкретную категорию и редакцию правил: название сети само по себе не даёт допуска.','Проверить возраст на нужную дату, класс, состав команды, coach, допустимую платформу и язык защиты.','Сохранить официальный результат: название этапа, категория, место / award, состав команды и ссылка на протокол.'],
        nuances=[records[0]['note']],cost='Бюджет: kit / компьютер, поле и сезонные детали, регистрация, подготовка, поездка и проживание. Точная сумма — в карточке этапа; не рассчитана для всей лиги.',
        award=records[0]['reward'],sources=[dict(title='Официальный источник '+e['id'],url=e['source'],checked=e['checked']) for e in records],evidence='Обзор по ранее проверенным карточкам; ограничения каждой площадки сохранены.'))
P={p['id']:p for p in profiles}
def source(title,url): return dict(title=title,url=url,checked=CHECKED)
def cat(name,age,team,hardware,age_rule,entry): return dict(name=name,age=age,team=team,hardware=hardware,age_rule=age_rule,entry=entry)
