def extra(key,name,age,tags,summary,categories,route,nuances,url):
    profiles.append(dict(id=key,name=name,group='advanced',age_summary=age,age_tags=tags.split(),summary=summary,categories=categories,event_ids=[],legacy_ids=[],route=route,hardware=categories[0]['hardware'],language='EN: международные материалы; язык национального отбора отдельно',importance='Сильная старшая траектория по профильной компетенции; редакционный ориентир, не общий мировой рейтинг.',strengths=summary,requirements=['Проверить действующие правила сезона и национального отбора до выбора представительства.','Подготовить самостоятельную работу и подтверждаемые результаты, а не только сертификаты курсов.'],nuances=nuances,cost='Точные расходы семьи не рассчитаны: подготовка, оборудование / вычисления, регистрация и поездка зависят от этапа.',award='Официальный результат конкретного этапа; квалификация и медаль — разные достижения.',sources=[source(name+': официальный источник',url)],evidence='Официальная страница / правила прочитаны 30.09.2026; локальные условия семьи не подтверждены.'))
extra('botball','Botball','Middle / high school; точные местные классы уточнить','unknown teen','Два автономных робота, программирование и документация инженерной работы.',[cat('Botball','Middle / high school','Команда; состав уточнить','KIPR Wombat и Botball kit; C / C++ / Java','Класс и местный сезон','Workshop → разработка → regional')],'KIPR / regional → workshop и kit → 7–9 недель разработки → regional. GCER и его доступ сверять отдельно.',['Junior Botball — отдельная младшая программа.','На странице нет универсального минимального возраста, численности команды и обещания автоматического места на мировом событии.'],'https://www.kipr.org/botball')
extra('robomaster','RoboMaster · University','Университетская команда; не младшая детская лига','university','Механика, электроника, computer vision, автономная навигация и большой командный проект.',[cat('RMUC','University','Команда университета','Несколько типов роботов; технические оценки','По статусу и Participant Manual','Университет → условия RMUC / RMUL → технические проверки → отбор')],'Университетская R&D-команда → сезонные условия входа → technical assessment → турнир и финальный отбор.',['Правила 2026 ограничивают вход RMUC историей команды или результатом RMUL; новый школьный клуб не получает прямого входа.','Детские турниры с RoboMaster EP и University Championship не являются одной возрастной лигой.','Долгосрочная возможность после школы, а не цель для ребёнка в 10–12.'],'https://www.robomaster.com/en-US/robo/rm')
extra('ioai','IOAI · Олимпиада по ИИ','≤20 на 1 июля + школьный статус; национальный отбор','teen','Профильная международная олимпиада по ИИ; школьная сборная страны.',[cat('IOAI · Student competition','≤20 на 1 июля','До 4 участников + взрослый team leader','Computing по syllabus / contest rules','Школьное обучение на / после 1 декабря предыдущего года','Признанный национальный отбор')],'Национальная олимпиада / признанный отбор → до 4 участников делегации → IOAI. Это не прямая семейная заявка.',['Национальные критерии и допуск по проживанию / учёбе должны подтвердить координаторы CR или MX.','WAICY / Codeavour не дают автоматическую квоту IOAI.','IOAI² AI Models Track для лабораторий отличается от школьной олимпиады.','Возраст не устанавливает готовность: маршрут ниже предлагает сначала Python, данные и математику.'],'https://ioai-official.org/wp-content/uploads/2025/08/IOAI-regulations.pdf')
extra('ioi','IOI · Олимпиада по информатике','≤20 на 1 июля; школа / без half-time degree','teen','Индивидуальные алгоритмические задачи на международном уровне.',[cat('IOI','≤20 на 1 июля','Индивидуальное соревнование; 1–4 в делегации','Среда программирования по contest rules','Учёба в школе в представляемой стране в сентябре–декабре предыдущего года; исключения по правилам','Национальный отбор')],'Школьные / национальные алгоритмические этапы → отбор делегации → IOI.',['Для учащихся за рубежом правила допускают представительство страны гражданства; конкретный национальный отбор и согласование обязательны.','Bebras / ACSL развивают базу, но сами не являются квалификацией IOI.','Это информатика, не соревнование по конструкции робота.'],'https://ioinformatics.org/files/regulations24-web.pdf')
extra('isef','Regeneron ISEF','9–12 классы; не достичь 20 к 1 мая перед ISEF','teen','Международный научно-инженерный конкурс с собственным исследованием.',[cat('ISEF · Science / Engineering','9–12 классы или эквивалент','Один / до 3','Исследовательский проект по профильной категории','Оба требования: класс + возраст до 20 на указанную дату','Только через ISEF-affiliated fair')],'Школьный проект → именно ISEF-affiliated fair → выделенная квота → ISEF. Обычная выставка не даёт такого прохода.',['Проект должен содержать собственное исследование; демонстрационный макет сам по себе недостаточен.','Работа, данные и вклад наставника описываются отдельно. Использование ИИ раскрывается; правила 2027 запрещают генерировать им research plan, abstract, poster и ссылки.','Школьная FCTI и вход ISEF не объединены автоматически: нужно найти действующий affiliated fair и его критерии.'],'https://www.societyforscience.org/isef/international-rules/rules-for-all-projects/')
